#nullable enable // autogenerated

using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.jackOLantern)]
    public class JackOLanternBuff : BuffDefinition
    {
        public JackOLanternBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicEntityProps.IS_LIGHT_SOURCE, true));
            AddModifier(new ColorModifier(LogicEntityProps.LIGHT_COLOR, Color.yellow));
            AddModifier(new Vector3Modifier(LogicEntityProps.LIGHT_RANGE, NumberOperator.Add, new Vector3(100, 100, 100)));
        }
    }
}


